import { cn } from '@/lib/utils'

// The "stamp": the monkey's head crop in a square ink frame.
// Generated by web/scripts/brand-assets.mjs from docs/brand/jungle-monkey.png.
export function Logo({ className }: { className?: string }) {
  return <img src="/brand/stamp-128.png" alt="" aria-hidden="true" width={128} height={128} className={cn('block shrink-0', className)} />
}
